from collections import defaultdict
from enum import Enum
from collections import deque
from time import sleep

COMPANIES = {


    "AAPLISH": {
        "name": "AAPLISH Inc.",
        "price": 175.42
    },
    "AMAZING": {
        "name": "AMAZING Enterprises",
