    },
    "ELONX": {
        "name": "ELONX Ventures",
        "price": 205.75
    },
    "CRUISEBOOK": {
        "name": "CRUISEBOOK Ltd.",
        "price": 186.94
    },
    "SNAPSTAR": {
        "name": "SNAPSTAR Innovations",
        "price": 142.09
    },
    "TWEETIFY": {
        "name": "TWEETIFY Solutions",
